// HubSpot's "Send a webhook" action posts the enrolled deal. Accept the shapes it uses
// (objectId at the top, or hs_object_id inside properties) and the event type from the URL.
const body = $input.first().json.body ?? {};
const query = $input.first().json.query ?? {};
const p = body.properties ?? {};
const raw = body.objectId ?? body.hs_object_id ?? p.hs_object_id?.value ?? p.hs_object_id;
const dealId = String(raw ?? '').trim();
if (!/^\d+$/.test(dealId)) throw new Error('No deal id in the HubSpot webhook body');
const event = query.event === 'stage' ? 'stage' : 'created';
return [{ json: { dealId, event } }];

// Block Kit message for #leads / #hot-leads.
const PORTAL = '247728856';
const STAGES = {
  '4456833770': 'New lead',
  '4456833771': 'Contacted',
  '4456833772': 'Call booked',
  '4456833773': 'Proposal sent',
  '4456833775': 'Closed won',
  '4456833776': 'Closed lost',
};
const LABELS = {
  'under-5k': 'Under $5k', '5k-15k': '$5k to $15k', '15k-50k': '$15k to $50k', '50k-plus': '$50k+', unsure: 'Not sure yet',
  asap: 'As soon as possible', '1-3-months': '1 to 3 months', '3-plus-months': '3+ months', exploring: 'Just exploring',
};
const { event, dealId } = $('Find deal id').first().json;
const deal = $('Read deal').first().json;
const d = deal.properties ?? {};
const contact = $('Read contact').first().json.properties ?? {};

// Slack mrkdwn: escape the three control characters in anything a visitor typed.
const esc = (s) => String(s ?? '').replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
const who = [contact.firstname, contact.lastname].filter(Boolean).join(' ') || 'Unknown contact';
const stage = STAGES[d.dealstage] ?? d.dealstage ?? 'Unknown stage';
const hot = d.tca_lead_bucket === 'Hot';
const url = 'https://app-na2.hubspot.com/contacts/' + PORTAL + '/record/0-3/' + dealId;
const claimed = Boolean(d.hubspot_owner_id);

const blocks = [];
if (event === 'stage') {
  blocks.push({ type: 'section', text: { type: 'mrkdwn', text: '*' + esc(d.dealname) + '* moved to *' + esc(stage) + '*' } });
  blocks.push({ type: 'actions', elements: [{ type: 'button', text: { type: 'plain_text', text: 'Open in HubSpot' }, url, action_id: 'open_deal' }] });
} else {
  blocks.push({ type: 'header', text: { type: 'plain_text', text: (hot ? 'Hot lead: ' : 'New lead: ') + String(d.dealname ?? who).slice(0, 140) } });
  blocks.push({
    type: 'section',
    fields: [
      { type: 'mrkdwn', text: '*Contact*\n' + esc(who) + (contact.email ? '\n' + esc(contact.email) : '') },
      { type: 'mrkdwn', text: '*Score*\n' + esc(d.tca_lead_score ?? '?') + '/15 (' + esc(d.tca_lead_bucket ?? 'unscored') + ')' },
      { type: 'mrkdwn', text: '*Budget*\n' + esc(LABELS[d.tca_budget] ?? d.tca_budget ?? '-') },
      { type: 'mrkdwn', text: '*Timeline*\n' + esc(LABELS[d.tca_timeline] ?? d.tca_timeline ?? '-') },
    ],
  });
  const actions = [{ type: 'button', text: { type: 'plain_text', text: 'Open in HubSpot' }, url, action_id: 'open_deal' }];
  if (!claimed) actions.unshift({ type: 'button', style: 'primary', text: { type: 'plain_text', text: 'Claim' }, action_id: 'claim_deal', value: dealId });
  blocks.push({ type: 'actions', elements: actions });
  blocks.push({ type: 'context', elements: [{ type: 'mrkdwn', text: 'Stage: ' + esc(stage) + (claimed ? ' · already has an owner' : ' · unclaimed') } ] });
}

return [{ json: {
  channel: hot ? 'C0CB16L6UD6' : 'C0CAAG03B1A',
  text: (event === 'stage' ? 'Deal moved: ' : hot ? 'Hot lead: ' : 'New lead: ') + esc(d.dealname ?? who),
  blocks,
  unfurl_links: false,
} }];

const r = $input.first().json;
if (r.ok === false) throw new Error('Slack API error: ' + r.error);
return $input.all();
